using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class AudioWorkspaceOperations
{
    private Control NewCurveEditor(Control o,GodotObject? clip)
    {
        var editor=GD.Load<GDScript>("res://Workspaces/AudioWorkspace/audio_automation_canvas.gd").New().As<Control>();editor.Set("session",Session(o));string track=Session(o).Get("selected_track").AsString();editor.Set("owner_kind",clip!=null?"clip":track.Length>0?"track":"master");editor.Set("owner_id",clip!=null?clip.Get("id").AsString():track);editor.Set("duration",Math.Max(1,clip!=null?clip.Get("duration").AsDouble():Document(o).Call("duration").AsDouble()));return editor;
    }
    public void automation_dialog(Control o)
    {
        var clip=Session(o).Call("primary_clip").AsGodotObject();string track=Session(o).Get("selected_track").AsString();if(clip==null&&_frameLanes.is_lane(Document(o).Call("track_for_id",track).AsGodotDictionary())){automation_lane_editor(o,track);return;}var dialog=window(o,"Automation and modulation",new Vector2I(720,580));var host=dialog["host"].As<Node>();var windowNode=dialog["window"].As<Window>();var editor=NewCurveEditor(o,clip);label(host,"Click to add a point; drag to move; right-click to remove. Clip time is relative to its start. Track/master time is absolute. Modulation becomes editable points shared by preview and export.");var row=new HFlowContainer();host.AddChild(row);string kind=editor.Get("owner_kind").AsString();var parameters=kind=="master"?new GArray{"volume_db"}:kind=="clip"?new GArray{"volume_db","pan","pitch"}:new GArray{"volume_db","pan"};ChoiceAction(o,row,"Parameter",parameters,"volume_db",value=>{editor.Set("parameter",value);editor.Set("minimum",value=="pitch"?.25:value=="pan"?-1:-60);editor.Set("maximum",value=="pitch"?4:value=="pan"?1:12);editor.QueueRedraw();});ChoiceAction(o,row,"Curve",new GArray{"linear","smooth","hold"},"linear",value=>editor.Call("set_curve",value));NumberAction(o,row,"View seconds",editor.Get("duration").AsDouble(),.1,3600,.1,value=>{editor.Set("duration",value);editor.QueueRedraw();});editor.SizeFlagsVertical=Control.SizeFlags.ExpandFill;host.AddChild(editor);var settings=new Settings{["shape"]="sine",["sync"]=true,["beats"]=1.0,["rate"]=1.0,["center"]=0.0,["depth"]=.5,["seed"]=1};var controls=new HFlowContainer();host.AddChild(controls);ChoiceAction(o,controls,"Modulator",new GArray{"sine","triangle","saw","square","random step","envelope"},"sine",value=>settings["shape"]=value);CheckAction(controls,"Beat sync",true,value=>settings["sync"]=value);foreach(var info in new[]{("beats","Beats/cycle",1.0,.0625,32.0,.0625),("rate","Rate (Hz)",1.0,.01,20.0,.01),("center","Center",0.0,-60.0,12.0,.1),("depth","Depth",.5,0.0,60.0,.1),("seed","Seed",1.0,0.0,2147483647.0,1.0)}){string key=info.Item1;NumberAction(o,controls,info.Item2,info.Item3,info.Item4,info.Item5,info.Item6,value=>{if(key=="seed")settings[key]=(long)value;else settings[key]=value;});}var actions=new HFlowContainer();host.AddChild(actions);ActionButton(actions,"Generate curve",()=>editor.Call("modulate",settings));ActionButton(actions,"Clear curve",()=>editor.Call("clear_points"));ActionButton(actions,"Show in timeline lane",()=>{show_automation_editor_in_lane(o,editor);windowNode.QueueFree();});label(host,"Gain and pan curves are sample-evaluated at export. Clip pitch is a ratio (1 = unchanged), requiring FFmpeg with Rubber Band for exact rendering. Open an effect’s Automation button for its supported parameter curves. Instrument modulation is baked with its note pattern.");
    }
    public void modulation_matrix_dialog(Control o)
    {
        var recording=Recording(o);if(Field<Node>(o,"recorder").Get("recording").AsBool()||o.Get("_record_busy").AsBool()||recording.Get("active").AsBool()||recording.Call("has_pending").AsBool()){notice(o,"Finish recording or automation before replacing curves.");return;}var owner=Session(o);var document=Document(o);var rows=Get(Dict(document,"presets"),"modulation_matrix",new GArray()).AsGodotArray().Duplicate(true);var options=_frameLanes.options(document);var dialog=window(o,"Modulation matrix · editable automation",new Vector2I(960,640));var windowNode=dialog["window"].As<Window>();var dialogHost=dialog["host"].As<Node>();var scroll=new ScrollContainer{SizeFlagsVertical=Control.SizeFlags.ExpandFill};dialogHost.AddChild(scroll);var host=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};scroll.AddChild(host);
        void Refresh(){clear(host);foreach(var raw in rows){var row=raw.AsGodotDictionary();var panel=new VBoxContainer();host.AddChild(panel);var chooser=new OptionButton{FitToLongestItem=false,ClipText=true};panel.AddChild(chooser);foreach(var option in options){chooser.AddItem(option["label"].AsString());chooser.SetItemMetadata(chooser.ItemCount-1,option["target"]);if(_frameLanes.key(option["target"].AsGodotDictionary())==_frameLanes.key(Get(row,"target",new Settings()).AsGodotDictionary()))chooser.Select(chooser.ItemCount-1);}chooser.ItemSelected+=index=>{row["target"]=chooser.GetItemMetadata((int)index).AsGodotDictionary().Duplicate(true);var info=_frameLanes.resolve(document,row["target"].AsGodotDictionary());row["center"]=Get(info,"fallback",0).AsDouble();};var controls=new HFlowContainer();panel.AddChild(controls);ChoiceAction(o,controls,"Source",new GArray{"sine","triangle","saw","square","random step","envelope"},Get(row,"shape","sine").AsString(),value=>row["shape"]=value);foreach(var info in new[]{("center","Center",0.0,-100000.0,100000.0,.1),("depth","Depth",1.0,-100000.0,100000.0,.1),("rate","Rate Hz",1.0,.01,20.0,.01),("beats","Period beats",1.0,.0625,64.0,.0625)}){string key=info.Item1;NumberAction(o,controls,info.Item2,Get(row,key,info.Item3).AsDouble(),info.Item4,info.Item5,info.Item6,value=>row[key]=value);}CheckAction(controls,"Sync to initial BPM",Get(row,"sync",false).AsBool(),value=>row["sync"]=value);ActionButton(controls,"Remove",()=>{rows.Remove(row);panel.QueueFree();});}}
        label(dialogHost,"Applies to clip/track/group/master gain/pan, clip pitch and supported effect parameters. Replaces each chosen curve in one Undo action; curves remain individually editable. BPM sync uses the initial conductor tempo, not variable-tempo following. Render exact preview for offline-only targets.");ActionButton(dialogHost,"Add target",()=>{if(rows.Count>=32)return;var target=options.Count>0?options[0]["target"].AsGodotDictionary():new Settings();rows.Add(new Settings{["target"]=target.Duplicate(true),["center"]=options.Count>0?options[0]["fallback"].AsDouble():0,["depth"]=1.0,["rate"]=1.0,["sync"]=false,["shape"]="sine",["beats"]=1.0});Refresh();});ActionButton(dialogHost,"Replace chosen curves · one Undo",()=>{if(Session(o)!=owner||Document(o)!=document){notice(o,"The document changed. Reopen the modulation matrix.");return;}using var matrix=new AudioModulationMatrixOperations();string error=matrix.apply(owner,rows);if(error.Length>0)notice(o,error);else windowNode.QueueFree();});Refresh();
    }
    public void modulator_dialog(Control o,bool generator)
    {
        var actor=Session(o).Call("primary_actor").AsGodotObject();if(!generator&&actor==null)return;var settings=generator?Dict(o,"_generator_settings"):Get(Dict(actor!,"values"),"instrument",new Settings()).AsGodotDictionary();var owner=Session(o);var document=Document(o);var dialog=window(o,"Synthesis modulation",new Vector2I(700,540));var windowNode=dialog["window"].As<Window>();var dialogHost=dialog["host"].As<Node>();var scroll=new ScrollContainer{SizeFlagsVertical=Control.SizeFlags.ExpandFill};dialogHost.AddChild(scroll);var host=new VBoxContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};scroll.AddChild(host);var modulators=Get(settings,"modulators",new GArray()).AsGodotArray().Duplicate(true);
        void Refresh(){clear(host);foreach(var raw in modulators){var modulator=raw.AsGodotDictionary();var row=new HFlowContainer();host.AddChild(row);ChoiceAction(o,row,"Target",new GArray{"pitch","cutoff","amplitude","pan"},Get(modulator,"target","pitch").AsString(),value=>modulator["target"]=value);ChoiceAction(o,row,"Source",new GArray{"lfo","envelope","random","step","velocity"},Get(modulator,"kind","lfo").AsString(),value=>modulator["kind"]=value);NumberAction(o,row,"Rate (Hz)",Get(modulator,"rate",1).AsDouble(),.01,30,.01,value=>modulator["rate"]=value);NumberAction(o,row,"Depth",Get(modulator,"amount",1).AsDouble(),-24,24,.1,value=>modulator["amount"]=value);var text=new System.Collections.Generic.List<string>();foreach(var value in Get(modulator,"values",new GArray{0,1,0,-1}).AsGodotArray())text.Add(value.AsDouble().ToString(System.Globalization.CultureInfo.InvariantCulture));var input=new LineEdit{PlaceholderText="Step values: 0,1,0,-1",Text=string.Join(",",text)};row.AddChild(input);input.TextChanged+=value=>{var steps=new GArray();foreach(string part in value.Split(',')){double.TryParse(part,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out double number);steps.Add(Math.Clamp(number,-24,24));}modulator["values"]=steps;};CheckAction(row,"Enabled",Get(modulator,"enabled",true).AsBool(),value=>modulator["enabled"]=value);}}Refresh();ActionButton(dialogHost,"Add modulation",()=>{modulators.Add(new Settings{["kind"]="lfo",["target"]="pitch",["rate"]=2.0,["amount"]=.5,["enabled"]=true,["values"]=new GArray{0,1,0,-1}});Refresh();});label(dialogHost,"Pitch depth is semitones; cutoff depth is octaves; amplitude depth is relative gain. Modulation is baked by synthesis. Seeded random and step sources are deterministic. Velocity uses each instrument note's velocity.");ActionButton(dialogHost,"Apply and preview",()=>{if(Session(o)!=owner||Document(o)!=document){notice(o,"The document changed. Reopen modulation.");return;}if(!generator){var clip=owner.Call("primary_clip").AsGodotObject();if(owner.Call("primary_actor").AsGodotObject()!=actor||clip==null||!owner.Call("can_edit",clip.Get("id")).AsBool()){notice(o,"Select the original unlocked instrument before applying modulation.");return;}}if(generator){settings["modulators"]=modulators;generate_preview(o);}else{SessionAction(o,"Instrument modulation",()=>{settings["modulators"]=modulators;Dict(actor!,"values")[new StringName("instrument")]=settings;Dict(actor!,"values")[new StringName("notes_dirty")]=true;});render_dirty_notes(o);}windowNode.QueueFree();});
    }
}
